<?php
require_once __DIR__.'/db.php';require_once __DIR__.'/includes/functions.php';require_role(['admin','manager']);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$st=$pdo->prepare("INSERT INTO rooms(dormitory_id,room_number,floor,capacity,status) VALUES(?,?,?,?,?)");$st->execute([(int)$_POST['dormitory_id'],trim($_POST['room_number']),(int)$_POST['floor'],(int)$_POST['capacity'],$_POST['status']]);flash('Ҳуҷра илова шуд.');redirect('rooms.php');}catch(Throwable $e){$error='Хатогӣ: рақами ҳуҷра такрорӣ ё маълумот нодуруст аст.';}}
$dorms=$pdo->query("SELECT id,name FROM dormitories ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT r.*,d.name dormitory_name,(SELECT COUNT(*) FROM allocations a WHERE a.room_id=r.id AND a.status='active') occupied FROM rooms r JOIN dormitories d ON d.id=r.dormitory_id ORDER BY d.name,r.room_number")->fetchAll();$pageTitle='Ҳуҷраҳо';require __DIR__.'/includes/header.php';?>
<h1>Ҳуҷраҳо</h1><?php if($error):?><div class="alert error"><?=$error?></div><?php endif;?><div class="panel"><h3>Иловаи ҳуҷра</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row"><div class="field"><label>Хобгоҳ</label><select name="dormitory_id" required><?php foreach($dorms as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="field"><label>Рақами ҳуҷра</label><input name="room_number" required></div><div class="field"><label>Ошёна</label><input type="number" name="floor" min="1" required></div><div class="field"><label>Ғунҷоиш</label><input type="number" name="capacity" min="1" required></div><div class="field"><label>Вазъият</label><select name="status"><option value="available">Холӣ</option><option value="maintenance">Таъмир</option></select></div></div><button>Сабт</button></form></div>
<div class="table-wrap"><table><tr><th>Хобгоҳ</th><th>Ҳуҷра</th><th>Ошёна</th><th>Ғунҷоиш</th><th>Ишғолшуда</th><th>Вазъият</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['dormitory_name'])?></td><td><?=e($r['room_number'])?></td><td><?=$r['floor']?></td><td><?=$r['capacity']?></td><td><?=$r['occupied']?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/includes/footer.php';?>
